  // Уже отправленный (полностью или частично) текст не переписываем.
  const good = (x) => base(x) && (!wantOpenAI || FORECAST_ACCEPTED_SOURCES.has(x.text_source) || !!x.sent_at || Number(x.telegram_next_part_index || 0) > 0);
